"""
Error handling utilities for HubSpot API interactions.
"""
import logging
import json
import functools
from typing import Any, Callable

from hubspot.crm.contacts.exceptions import ApiException

logger = logging.getLogger('mcp_hubspot_client.error_handler')

def handle_hubspot_errors(func: Callable) -> Callable:
    """Decorator to handle HubSpot API errors consistently.

    Args:
        func: Function to wrap with error handling

    Returns:
        Wrapped function with error handling
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        try:
            return func(*args, **kwargs)
        except ApiException as e:
            logger.error(f"API Exception in {func.__name__}: {str(e)}")
            return json.dumps({"error": str(e)})
        except Exception as e:
            logger.error(f"Exception in {func.__name__}: {str(e)}")
            return json.dumps({"error": str(e)})
    return wrapper

#!/usr/bin/env python
"""
Test script for retrieving closed tickets from HubSpot.
This script directly uses the HubSpot client to test different approaches
to get closed tickets and provides detailed debug output.
"""
import os
import sys
import json
import logging
from typing import Dict, Any, List, Optional
from datetime import datetime

# Add src directory to path to allow direct imports
sys.path.append(os.path.join(os.path.dirname(__file__), "src"))

# Import HubSpot client
from mcp_server_hubspot.hubspot_client import HubSpotClient
from hubspot import HubSpot
from hubspot.crm.tickets import PublicObjectSearchRequest

# Configure logging
logging.basicConfig(
    level=logging.DEBUG,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger("test_closed_tickets")

class TicketTester:
    """Test different approaches to get closed tickets from HubSpot."""

    def __init__(self, access_token: [REDACTED]] = None):
        """Initialize with HubSpot API token.

        Args:
            access_token: HubSpot API token (if None, uses HUBSPOT_ACCESS_TOKEN env var)
        """
        self.access_token = [REDACTED] or os.getenv("HUBSPOT_ACCESS_TOKEN")
        if not self.access_token:
            raise ValueError("HUBSPOT_ACCESS_TOKEN environment variable is required")

        # Initialize HubSpot client
        self.hubspot_client = HubSpotClient(self.access_token)
        self.direct_client = HubSpot(access_token=[REDACTED]

        logger.info("HubSpot client initialized")

    def test_get_tickets_standard(self):
        """Test getting closed tickets using the standard client method."""
        logger.info("Testing standard client method with 'Closed' value")
        try:
            results = self.hubspot_client.get_tickets(
                criteria="Closed",
                limit=20,
                max_retries=3,
                retry_delay=1.0
            )
            logger.info(f"Results: {json.dumps(results, indent=2)}")
            return results
        except Exception as e:
            logger.error(f"Error using standard method: {str(e)}", exc_info=True)
            return {"error": str(e)}

    def test_get_tickets_lowercase(self):
        """Test getting closed tickets using lowercase 'closed'."""
        logger.info("Testing standard client method with lowercase 'closed' value")
        try:
            # This is a workaround that bypasses type checking
            results = self.hubspot_client.tickets.get_tickets(
                criteria="closed",  # lowercase to match current implementation
                limit=20,
                max_retries=3,
                retry_delay=1.0
            )
            logger.info(f"Results: {json.dumps(results, indent=2)}")
            return results
        except Exception as e:
            logger.error(f"Error using lowercase method: {str(e)}", exc_info=True)
            return {"error": str(e)}

    def test_direct_search_api(self):
        """Test getting closed tickets using direct search API with multiple filters."""
        logger.info("Testing direct search API with multiple filter approaches")

        # Try multiple approaches to filter for closed tickets
        filter_groups_approaches = [
            # Approach 1: Using hs_pipeline_stage=closed
            [{
                "filters": [{
                    "propertyName": "hs_pipeline_stage",
                    "operator": "EQ",
                    "value": "closed"
                }]
            }],

            # Approach 2: Using hs_pipeline_stage=CLOSED (uppercase)
            [{
                "filters": [{
                    "propertyName": "hs_pipeline_stage",
                    "operator": "EQ",
                    "value": "CLOSED"
                }]
            }],

            # Approach 3: Using hs_ticket_status=CLOSED
            [{
                "filters": [{
                    "propertyName": "hs_ticket_status",
                    "operator": "EQ",
                    "value": "CLOSED"
                }]
            }],

            # Approach 4: Using status=CLOSED
            [{
                "filters": [{
                    "propertyName": "status",
                    "operator": "EQ",
                    "value": "CLOSED"
                }]
            }],

            # Approach 5: Using pipeline stage contains "closed"
            [{
                "filters": [{
                    "propertyName": "hs_pipeline_stage",
                    "operator": "CONTAINS_TOKEN",
                    "value": "closed"
                }]
            }]
        ]

        results = []

        # Try each approach
        for idx, filter_groups in enumerate(filter_groups_approaches):
            approach_name = f"Approach {idx+1}"
            logger.info(f"Trying {approach_name}")
            try:
                # Create search request
                search_request = PublicObjectSearchRequest(
                    filter_groups=filter_groups,
                    sorts=[{
                        "propertyName": "hs_lastmodifieddate",
                        "direction": "DESCENDING"
                    }],
                    limit=20,
                    properties=[
                        "subject", 
                        "content", 
                        "hs_pipeline", 
                        "hs_pipeline_stage", 
                        "hs_ticket_status",
                        "status",
                        "hs_ticket_priority", 
                        "createdate", 
                        "closedate", 
                        "hs_lastmodifieddate"
                    ]
                )

                # Execute search
                search_response = self.direct_client.crm.tickets.search_api.do_search(
                    public_object_search_request=search_request
                )

                # Convert results to dict
                tickets_dict = [ticket.to_dict() for ticket in search_response.results]

                # Store results
                result = {
                    "approach": approach_name,
                    "filter": filter_groups,
                    "count": len(tickets_dict),
                    "tickets": tickets_dict
                }
                results.append(result)

                logger.info(f"{approach_name} found {len(tickets_dict)} tickets")
                if tickets_dict:
                    # If we found tickets, log the first one's details
                    logger.info(f"First ticket sample: {json.dumps(tickets_dict[0], indent=2)}")

            except Exception as e:
                logger.error(f"Error with {approach_name}: {str(e)}", exc_info=True)
                results.append({
                    "approach": approach_name,
                    "filter": filter_groups,
                    "error": str(e)
                })

        return results

    def test_get_pipelines(self):
        """Test getting pipeline information to understand ticket stages."""
        logger.info("Getting pipeline information")
        try:
            pipelines = self.direct_client.crm.pipelines.pipelines_api.get_all("tickets")

            pipeline_data = []
            for pipeline in pipelines.results:
                stages = []
                for stage in pipeline.stages:
                    stages.append({
                        "id": stage.id,
                        "label": stage.label,
                        "display_order": stage.display_order,
                        "is_closed": getattr(stage, "is_closed", False)
                    })

                pipeline_data.append({
                    "id": pipeline.id,
                    "label": pipeline.label,
                    "display_order": pipeline.display_order,
                    "stages": stages
                })

            logger.info(f"Pipeline data: {json.dumps(pipeline_data, indent=2)}")
            return pipeline_data
        except Exception as e:
            logger.error(f"Error getting pipelines: {str(e)}", exc_info=True)
            return {"error": str(e)}


def main():
    """Run all tests and print results."""
    tester = TicketTester()

    # Test 1: Get pipeline information
    print("\n=== Pipeline Information ===")
    pipeline_data = tester.test_get_pipelines()
    print(f"Found {len(pipeline_data)} pipelines")

    # Test 2: Standard method
    print("\n=== Standard Method with 'Closed' ===")
    standard_results = tester.test_get_tickets_standard()

    # Test 3: Lowercase method
    print("\n=== Lowercase Method with 'closed' ===")
    lowercase_results = tester.test_get_tickets_lowercase()

    # Test 4: Direct search API with multiple approaches
    print("\n=== Direct Search API with Multiple Approaches ===")
    direct_results = tester.test_direct_search_api()

    # Save all results to a file
    all_results = {
        "timestamp": datetime.now().isoformat(),
        "pipelines": pipeline_data,
        "standard_method": standard_results,
        "lowercase_method": lowercase_results,
        "direct_search": direct_results
    }

    output_file = "closed_ticket_test_results.json"
    with open(output_file, "w") as f:
        json.dump(all_results, f, indent=2)

    print(f"\nAll test results saved to {output_file}")

    # Print summary
    print("\n=== Summary ===")
    print(f"Pipelines: {len(pipeline_data)}")

    # Handle standard results
    if isinstance(standard_results, dict) and "error" in standard_results:
        print(f"Standard method: Error - {standard_results['error']}")
    elif isinstance(standard_results, dict):
        print(f"Standard method: {len(standard_results.get('results', []))} tickets")
    else:
        print(f"Standard method: Unexpected result format")

    # Handle lowercase results - it might be a JSON string
    if isinstance(lowercase_results, str):
        try:
            # Try to parse it as JSON
            lowercase_dict = json.loads(lowercase_results)
            if "error" in lowercase_dict:
                print(f"Lowercase method: Error - {lowercase_dict['error']}")
            else:
                print(f"Lowercase method: {len(lowercase_dict.get('results', []))} tickets")
        except json.JSONDecodeError:
            print(f"Lowercase method: Error - {lowercase_results}")
    elif isinstance(lowercase_results, dict) and "error" in lowercase_results:
        print(f"Lowercase method: Error - {lowercase_results['error']}")
    elif isinstance(lowercase_results, dict):
        print(f"Lowercase method: {len(lowercase_results.get('results', []))} tickets")
    else:
        print(f"Lowercase method: Unexpected result format")

    # Handle direct search results
    print("Direct search results:")
    for result in direct_results:
        if "error" in result:
            print(f"  {result['approach']}: Error")
        else:
            print(f"  {result['approach']}: {result.get('count', 0)} tickets")


if __name__ == "__main__":
    main()

"""
Handler for company-related HubSpot operations.
"""
from typing import Any, Dict, List, Optional
import json

import mcp.types as types

from ..hubspot_client import HubSpotClient, ApiException
from ..faiss_manager import FaissManager
from .base_handler import BaseHandler

class CompanyHandler(BaseHandler):
    """Handler for company-related HubSpot tools."""

    def __init__(self, hubspot_client, faiss_manager, embedding_model):
        """Initialize the company handler.

        Args:
            hubspot_client: HubSpot client
            faiss_manager: FAISS vector store manager
            embedding_model: Sentence transformer model
        """
        super().__init__(hubspot_client, faiss_manager, embedding_model, "company_handler")

    def get_create_company_schema(self) -> Dict[str, Any]:
        """Get the input schema for creating a company.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "name": {"type": "string", "description": "Company name"},
                "properties": {"type": "object", "description": "Additional company properties"}
            },
            "required": ["name"]
        }

    def get_company_activity_schema(self) -> Dict[str, Any]:
        """Get the input schema for company activity.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "company_id": {"type": "string", "description": "HubSpot company ID"}
            },
            "required": ["company_id"]
        }

    def get_active_companies_schema(self) -> Dict[str, Any]:
        """Get the input schema for active companies.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "limit": {"type": "integer", "description": "Maximum number of companies to return (default: 10)"}
            }
        }

    def get_company_schema(self) -> Dict[str, Any]:
        """Get the input schema for getting a company by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "company_id": {"type": "string", "description": "HubSpot company ID"},
                "properties": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Optional list of properties to retrieve. If omitted, returns all properties."
                }
            },
            "required": ["company_id"]
        }

    def get_update_company_schema(self) -> Dict[str, Any]:
        """Get the input schema for updating a company by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "company_id": {"type": "string", "description": "HubSpot company ID to update"},
                "properties": {
                    "type": "object",
                    "description": "Object containing the properties to update"
                }
            },
            "required": ["company_id", "properties"]
        }

    def create_company(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Create a new company in HubSpot.

        Args:
            arguments: Tool arguments containing company information

        Returns:
            Text response with result
        """
        self.validate_required_arguments(arguments, ["name"])

        try:
            from hubspot.crm.companies import PublicObjectSearchRequest

            company_name = arguments["name"]

            # Search for existing companies with same name
            search_request = PublicObjectSearchRequest(
                filter_groups=[{
                    "filters": [
                        {
                            "propertyName": "name",
                            "operator": "EQ",
                            "value": company_name
                        }
                    ]
                }]
            )

            search_response = self.hubspot.client.crm.companies.search_api.do_search(
                public_object_search_request=search_request
            )

            if search_response.total > 0:
                # Company already exists
                return self.create_text_response(
                    f"Company already exists: {search_response.results[0].to_dict()}"
                )

            # If no existing company found, proceed with creation
            properties = {
                "name": company_name
            }

            # Add any additional properties
            if "properties" in arguments:
                properties.update(arguments["properties"])

            # Create company using SimplePublicObjectInputForCreate
            from hubspot.crm.companies import SimplePublicObjectInputForCreate

            simple_public_object_input = SimplePublicObjectInputForCreate(
                properties=properties
            )

            api_response = self.hubspot.client.crm.companies.basic_api.create(
                simple_public_object_input_for_create=simple_public_object_input
            )
            return self.create_text_response(str(api_response.to_dict()))

        except ApiException as e:
            return self.create_text_response(f"HubSpot API error: {str(e)}")
        except Exception as e:
            return self.create_text_response(f"Error: {str(e)}")

    def get_company_activity(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get activity history for a specific company.

        Args:
            arguments: Tool arguments containing company ID

        Returns:
            Text response with company activity data
        """
        self.validate_required_arguments(arguments, ["company_id"])

        results = self.hubspot.get_company_activity(arguments["company_id"])

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"company_id": arguments["company_id"]}
            self.store_in_faiss_safely(data, "company_activity", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing company activity data: {str(e)}")

        return self.create_text_response(results)

    def get_active_companies(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get most recently active companies from HubSpot.

        Args:
            arguments: Tool arguments containing limit parameter

        Returns:
            Text response with company data
        """
        limit = self.get_argument_with_default(arguments, "limit", 10)

        # Ensure limit is an integer
        limit = int(limit) if limit is not None else 10

        results = self.hubspot.get_recent_companies(limit=limit)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"limit": limit}
            self.store_in_faiss_safely(data, "company", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing company data: {str(e)}")

        return self.create_text_response(results)

    def get_company(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get a specific company by ID from HubSpot.

        Args:
            arguments: Tool arguments containing company_id and optional properties

        Returns:
            Text response with company data
        """
        self.validate_required_arguments(arguments, ["company_id"])

        company_id = arguments["company_id"]
        properties = arguments.get("properties")

        results = self.hubspot.get_company_by_id(company_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"company_id": company_id}
            self.store_in_faiss_safely(data, "company", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing company data: {str(e)}")

        return self.create_text_response(results)

    def update_company(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Update a specific company by ID in HubSpot.

        Args:
            arguments: Tool arguments containing company_id and properties to update

        Returns:
            Text response with updated company data
        """
        self.validate_required_arguments(arguments, ["company_id", "properties"])

        company_id = arguments["company_id"]
        properties = arguments["properties"]

        results = self.hubspot.update_company(company_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"company_id": company_id, "updated": True}
            self.store_in_faiss_safely(data, "company", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing updated company data: {str(e)}")

        return self.create_text_response(results)

"""
Handler for contact-related HubSpot operations.
"""
from typing import Any, Dict, List, Optional
import json

import mcp.types as types

from ..hubspot_client import ApiException
from .base_handler import BaseHandler

class ContactHandler(BaseHandler):
    """Handler for contact-related HubSpot tools."""

    def __init__(self, hubspot_client, faiss_manager, embedding_model):
        """Initialize the contact handler.

        Args:
            hubspot_client: HubSpot client
            faiss_manager: FAISS vector store manager
            embedding_model: Sentence transformer model
        """
        super().__init__(hubspot_client, faiss_manager, embedding_model, "contact_handler")

    def get_create_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for creating a contact.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "firstname": {"type": "string", "description": "Contact's first name"},
                "lastname": {"type": "string", "description": "Contact's last name"},
                "email": {"type": "string", "description": "Contact's email address"},
                "properties": {"type": "object", "description": "Additional contact properties"}
            },
            "required": ["firstname", "lastname"]
        }

    def get_active_contacts_schema(self) -> Dict[str, Any]:
        """Get the input schema for active contacts.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "limit": {"type": "integer", "description": "Maximum number of contacts to return (default: 10)"}
            }
        }

    def get_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for getting a contact by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "contact_id": {"type": "string", "description": "HubSpot contact ID"},
                "properties": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Optional list of properties to retrieve. If omitted, returns all properties."
                }
            },
            "required": ["contact_id"]
        }

    def get_update_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for updating a contact by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "contact_id": {"type": "string", "description": "HubSpot contact ID to update"},
                "properties": {
                    "type": "object",
                    "description": "Object containing the properties to update"
                }
            },
            "required": ["contact_id", "properties"]
        }

    def create_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Create a new contact in HubSpot.

        Args:
            arguments: Tool arguments containing contact information

        Returns:
            Text response with result
        """
        self.validate_required_arguments(arguments, ["firstname", "lastname"])

        try:
            from hubspot.crm.contacts import PublicObjectSearchRequest

            firstname = arguments["firstname"]
            lastname = arguments["lastname"]
            company = arguments.get("properties", {}).get("company")

            # Search for existing contacts with same name and company
            filter_groups = [{
                "filters": [
                    {
                        "propertyName": "firstname",
                        "operator": "EQ",
                        "value": firstname
                    },
                    {
                        "propertyName": "lastname",
                        "operator": "EQ",
                        "value": lastname
                    }
                ]
            }]

            # Add company filter if provided
            if company:
                filter_groups[0]["filters"].append({
                    "propertyName": "company",
                    "operator": "EQ",
                    "value": company
                })

            search_request = PublicObjectSearchRequest(
                filter_groups=filter_groups
            )

            search_response = self.hubspot.client.crm.contacts.search_api.do_search(
                public_object_search_request=search_request
            )

            if search_response.total > 0:
                # Contact already exists
                return self.create_text_response(
                    f"Contact already exists: {search_response.results[0].to_dict()}"
                )

            # If no existing contact found, proceed with creation
            properties = {
                "firstname": firstname,
                "lastname": lastname
            }

            # Add email if provided
            if "email" in arguments:
                properties["email"] = arguments["email"]

            # Add any additional properties
            if "properties" in arguments:
                properties.update(arguments["properties"])

            # Create contact using SimplePublicObjectInputForCreate
            from hubspot.crm.contacts import SimplePublicObjectInputForCreate

            simple_public_object_input = SimplePublicObjectInputForCreate(
                properties=properties
            )

            api_response = self.hubspot.client.crm.contacts.basic_api.create(
                simple_public_object_input_for_create=simple_public_object_input
            )
            return self.create_text_response(str(api_response.to_dict()))

        except ApiException as e:
            return self.create_text_response(f"HubSpot API error: {str(e)}")
        except Exception as e:
            return self.create_text_response(f"Error: {str(e)}")

    def get_active_contacts(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get most recently active contacts from HubSpot.

        Args:
            arguments: Tool arguments containing limit parameter

        Returns:
            Text response with contact data
        """
        limit = self.get_argument_with_default(arguments, "limit", 10)

        # Ensure limit is an integer
        limit = int(limit) if limit is not None else 10

        results = self.hubspot.get_recent_contacts(limit=limit)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"limit": limit}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing contact data: {str(e)}")

        return self.create_text_response(results)

    def get_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get a specific contact by ID from HubSpot.

        Args:
            arguments: Tool arguments containing contact_id and optional properties

        Returns:
            Text response with contact data
        """
        self.validate_required_arguments(arguments, ["contact_id"])

        contact_id = arguments["contact_id"]
        properties = arguments.get("properties")

        results = self.hubspot.get_contact_by_id(contact_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"contact_id": contact_id}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing contact data: {str(e)}")

        return self.create_text_response(results)

    def update_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Update a specific contact by ID in HubSpot.

        Args:
            arguments: Tool arguments containing contact_id and properties to update

        Returns:
            Text response with updated contact data
        """
        self.validate_required_arguments(arguments, ["contact_id", "properties"])

        contact_id = arguments["contact_id"]
        properties = arguments["properties"]

        results = self.hubspot.update_contact(contact_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"contact_id": contact_id, "updated": True}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing updated contact data: {str(e)}")

        return self.create_text_response(results)
